<?php use CmuLms\View; $title='Course gradebook'; include __DIR__.'/../layout/header.php'; ?>
<section class="hero"><span><?=View::e($course['code'])?> · Teacher gradebook</span><h1><?=View::e($course['title'])?></h1><p>Review scores for this subject.</p></section>
<section class="card"><div style="display:flex;justify-content:space-between;gap:1rem;align-items:center;flex-wrap:wrap"><h2>Student overview</h2><a class="btn" href="?route=course-gradebook-export&amp;id=<?=View::e($course['id'])?>">Export CSV</a></div><p class="muted">All active students are shown, including learners with no released grades yet.</p><div style="overflow-x:auto"><table><tr><th>Student</th><th>School ID</th><th>Average</th><th>Released items</th><th>Status</th></tr><?php foreach($learners as $learner): $summary=$summaries[(int)$learner['id']]; ?><tr><td><?=View::e($learner['name'])?></td><td><?=View::e($learner['id_number'])?></td><td><?= $summary['weighted_average']===null?'—':View::e(number_format($summary['weighted_average'],2).'%') ?></td><td><?=View::e($summary['graded_items'])?></td><td><?= $summary['graded_items']?'In progress':'No grades yet' ?></td></tr><?php endforeach; ?><?php if(!$learners): ?><tr><td colspan="5">No active students are enrolled in this course.</td></tr><?php endif; ?></table></div></section>
<section class="card"><h2>Assessment details</h2><div style="overflow-x:auto"><table><tr><th>Student</th><th>School ID</th><th>Assessment</th><th>Category</th><th>Score</th><th>Released</th></tr><?php foreach($grades as $grade): ?><tr><td><?=View::e($grade['name'])?></td><td><?=View::e($grade['id_number'])?></td><td><?=View::e($grade['title'])?></td><td><?=View::e($grade['category'])?></td><td><?=View::e($grade['score'])?> / <?=View::e($grade['max_score'])?></td><td><?=!empty($grade['released'])?'Yes':'No'?></td></tr><?php endforeach; ?><?php if(!$grades): ?><tr><td colspan="6">No released assessment grades recorded yet.</td></tr><?php endif; ?></table></div></section>
<?php include __DIR__.'/quiz-results.php'; ?>
<section class="card"><h2>Grade weights</h2><p class="muted">Configure category weights for this course.</p><form method="post" action="?route=grade-weights"><?=View::csrfField()?><input type="hidden" name="course_id" value="<?=View::e($course['id'])?>"><div class="grid"><?php foreach($weights as $weight): ?><input name="category[]" value="<?=View::e($weight['category'])?>" placeholder="Category"><input name="weight[]" type="number" min="0" max="100" step="0.01" value="<?=View::e($weight['weight'])?>" placeholder="Weight %"><?php endforeach; ?><input name="category[]" placeholder="Category"><input name="weight[]" type="number" min="0" max="100" step="0.01" placeholder="Weight %"></div><button>Save weights</button></form></section>
